	@Test
	void underestimatedPrefixRetainsTheActualRepeatedScanCeiling() throws Exception {
		measure(0.25D);
	}

	@Test
	void accuratePrefixRetainsTheActualRepeatedScanControl() throws Exception {
		measure(1D);
	}

	private void measure(double estimateFraction) throws Exception {
		Map<Value, Integer> expected = new LinkedHashMap<>();
		for (int i = 0; i < SUBJECTS; i++) {
			for (int j = 0; j < PROBE_PER_SUBJECT; j++) {
				expected.put(iri("probeValue" + i + "-" + j), BUILD_PER_SUBJECT);
			}
		}
		assertThat(bag(memoryRepository, QUERY)).as("MemoryStore exact bag").isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(bag(repository, QUERY)).as("generic LMDB exact bag").isEqualTo(expected);
		set(NATIVE, "true");
		Optimized optimized = optimizeAndRun(QUERY);
		assertThat(optimized.bag()).isEqualTo(expected);
		var previousContext = SlowQueryContextHolder.set("hash repeated scan ceiling", Query.QueryType.TUPLE, ROUTE);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource actual = (NativeLmdbQuerySource) dataset;
			CountedSource counted = new CountedSource(actual, actual.idOf(BUILD), actual.idOf(PROBE));
			assertThat(actual.indexAccessProfile().entries()).isEqualTo(PROBE_ROWS);
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false);
			assertThat(strategy.forcedExecutionStrategyName()).isEqualTo(ROUTE);
			TupleExpr parsed = optimized.expression();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(parsed,
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, counted.source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep template = (NativeRowsStep) compiled;
			assertThat(template.arg).isInstanceOf(MultiJoinPlan.class);
			MultiJoinPlan original = (MultiJoinPlan) template.arg;
			assertThat(original.children).hasSize(2);
			assertThat(original.filters).isEmpty();
			assertThat(template.optionalOnlyNames).isEmpty();
			assertThat(template.snapshotRows).isFalse();
			SlotPlan[] inputs = new SlotPlan[2];
			for (int i = 0; i < inputs.length; i++) {
				assertThat(original.children[i]).isInstanceOf(PatternPlan.class);
				PatternPlan pattern = (PatternPlan) original.children[i];
				double actualRows = pattern.p.constant == counted.buildPredicate ? BUILD_ROWS : PROBE_ROWS;
				assertThat(pattern.p.constant).isIn(counted.buildPredicate, counted.probePredicate);
				assertThat(pattern.staticEstimate).isEqualTo(actualRows);
				inputs[i] = new PatternPlan(pattern.s, pattern.p, pattern.o, pattern.c, pattern.contexts,
						pattern.namedContextScope, pattern.statementOrder, pattern.indexName, pattern.range,
						actualRows * estimateFraction, pattern.accessProfile);
			}
			NativeRowsStep step = new NativeRowsStep(template.source, new MultiJoinPlan(inputs, original.filters),
					template.layout, template.sourceSlots, template.targetNames, template.distinct,
					template.orderSlots, template.orderAscending, template.offset, template.limit,
					template.strictCompare, strategy, template.originalExpr, template.context, Set.of(),
					template.prefixPattern, template.prefixRunPlan);
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				MultiJoinPlan join = (MultiJoinPlan) step.arg;
				LmdbNativeHashJoin.KernelHashPlan planned = LmdbNativeKernelLowering.preferredRowHashPlan(join, row);
				assertThat(planned).as("positive sampled inputs still admit the preferred real hash plan").isNotNull();
				assertThat(planned.build.p.constant).isEqualTo(counted.buildPredicate);
				assertThat(planned.buildRowsEstimate).isEqualTo(BUILD_ROWS * estimateFraction);
				SlotPlan[] order = join.derivedPlanForLowering(row, 0L).order;
				assertThat(order).hasSize(2);
				assertThat(LmdbNativeCostVectors.rows(order[0], row, 0L)).isEqualTo(BUILD_ROWS * estimateFraction);
				LmdbNativeAccessFacts.Quote access = LmdbNativeAccessFacts.forPattern(planned.probe, row.source)
						.quote(planned.probe.physicalMask(planned.build.producedMask()));
				assertThat(access.selectedSource()).as("the nominal quote prefers the advertised adjacency")
						.isEqualTo(LmdbNativeAccessFacts.Source.ADJACENCY);
				assertThat(access.prefixMask()).as("the real spoc index covers this subject/predicate run")
						.isEqualTo(LmdbNativeAccessFacts.SUBJECT | LmdbNativeAccessFacts.PREDICATE);
				assertThat(access.residualFields()).isZero();
				assertThat(access.scannedRows()).isEqualTo(PROBE_ROWS);
				assertThat(planned.probe.o.isConstant()).isFalse();
				assertThat(planned.probe.producedMask() & planned.build.producedMask())
						.isEqualTo(1L << planned.build.s.slot);
				long beforeQuote = LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get();
				LmdbNativeCostQuote quote = LmdbNativeKernelHashCostQuote.quote(join, row, Feature.INTERPRETED_ROW,
						LmdbNativeWork.rowsOut(join, row, 0L), LmdbNativeKernelExecution.rowFillSize(true));
				assertThat(quote).isNotNull();
				assertThat(LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get()).isEqualTo(beforeQuote);
				assertThat(counted.probeHandles + counted.scanOpens).as("cost construction is storage-free").isZero();
				LmdbNativeKernelLowering.Lowered preferred = LmdbNativeKernelLowering.lowerRows(join, row, parsed,
						false);
				assertThat(preferred).isNotNull();
				assertThat(nodes(preferred)).anyMatch(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.anyMatch(LmdbNativeKernelIr.HashProbe.class::isInstance);
				LmdbNativeKernelLowering.Lowered fallback = LmdbNativeKernelLowering.lowerRows(join, row, parsed, true);
				assertThat(fallback).isNotNull();
				assertThat(nodes(fallback)).noneMatch(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.noneMatch(LmdbNativeKernelIr.HashProbe.class::isInstance);
				assertThat(nodes(fallback).stream().filter(LmdbNativeKernelIr.ScanQuad.class::isInstance)).hasSize(2);
				assertThat(fallback.bindings.adjacencies).isEmpty();
				assertThat(fallback.kernel.resumable).isTrue();
			} finally {
				row.memoryScope.close();
			}
			assertThat(counted.probeHandles + counted.scanOpens).as("preflight does not execute inputs").isZero();
			List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
			long binds = LmdbNativeKernelExecution.INTERPRETED_BINDS.get();
			long producedBefore = LmdbNativeKernelExecution.KERNEL_ROWS.get();
			LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
				if (record.point() == LmdbNativeDecisionPoint.ROW) {
					assertThat(id).isEqualTo(ROUTE);
					selected.add(
							record.entries().stream().filter(entry -> entry.id().equals(id)).findFirst().orElseThrow());
				}
			});
			Map<Value, Integer> result = new LinkedHashMap<>();
			try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					result.merge(rows.next().getValue("value"), 1, Integer::sum);
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(result).as("the actual relowered serial IR scan chain's bag").isEqualTo(expected);
			assertThat(selected).hasSize(1);
			assertThat(LmdbNativeKernelExecution.INTERPRETED_BINDS.get()).isGreaterThan(binds);
			assertThat(LmdbNativeKernelExecution.KERNEL_ROWS.get() - producedBefore)
					.isEqualTo(BUILD_ROWS * PROBE_PER_SUBJECT);
			assertThat(counted.buildRefusals).as("the actual hash opener encountered the unavailable build view")
					.isPositive();
			assertThat(counted.buildOpens).as("the fallback enumerates its prefix once").isEqualTo(1);
			assertThat(counted.buildReturned).isEqualTo(BUILD_ROWS);
			assertThat(counted.probeOpens).as("one actual run scan per real prefix row, not a hash probe pass")
					.isEqualTo(BUILD_ROWS);
			assertThat(counted.probeReturned).isEqualTo(BUILD_ROWS * PROBE_PER_SUBJECT);
			assertThat(counted.scanCloses).isEqualTo(counted.scanOpens);
			assertThat(counted.closedProbeHandles).isEqualTo(counted.probeHandles);
			assertThat(counted.probeScanned).as("every real prefix row reopens the complete nonempty run")
					.isGreaterThanOrEqualTo((long) BUILD_ROWS * PROBE_ROWS);
			LmdbNativeCostVector features = selected.getFirst().features();
			assertThat(features.expected(Feature.HASH_BUILD_ROW)).isEqualTo(BUILD_ROWS * estimateFraction);
			long actualScanned = counted.buildScanned + counted.probeScanned;
			System.out.printf("hash retry fraction=%.2f prefix=%d childOpens=%d rawScanned=%d quoteHigh=%.3f%n",
					estimateFraction, counted.buildReturned, counted.probeOpens, actualScanned,
					features.high(Feature.SCANNED_ROW));
			assertThat(features.high(Feature.SCANNED_ROW))
					.as("a sampled prefix cannot cap the actually reopened LMDB work")
					.isGreaterThanOrEqualTo(actualScanned);
		} finally {
			SlowQueryContextHolder.restore(previousContext);
		}
	}

	private static List<LmdbNativeKernelIr.Node> nodes(LmdbNativeKernelLowering.Lowered lowered) {
		List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
		LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
		return nodes;
	}

	private static IRI iri(String suffix) {
		return SimpleValueFactory.getInstance().createIRI(NS + suffix);
	}

	/** Capture the unmodified optimized query and bag before the separate estimate-uncertainty injection. */
	private Optimized optimizeAndRun(String query) {
		List<TupleExpr> optimized = new ArrayList<>();
		Map<Value, Integer> bag = new LinkedHashMap<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				assertThat(id).isEqualTo(ROUTE);
				assertThat(target).isNotNull();
				optimized.add(target.clone());
			}
		});
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(ROUTE);
			prepared.setMaxExecutionTime(10);
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					bag.merge(rows.next().getValue("value"), 1, Integer::sum);
				}
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(optimized).as("one actual optimized repository dispatch").hasSize(1);
		return new Optimized(optimized.getFirst(), bag);
	}

	private record Optimized(TupleExpr expression, Map<Value, Integer> bag) {
	}

	private static Map<Value, Integer> bag(SailRepository repository, String query) {
		Map<Value, Integer> bag = new LinkedHashMap<>();
		try (var connection = repository.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			while (rows.hasNext()) {
				bag.merge(rows.next().getValue("value"), 1, Integer::sum);
			}
		}
		return bag;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}

	/**
	 * Keep all metadata real, refuse the build's executable adjacency view, and serve the resulting ordinary probe
	 * opens from the actual LMDB index. This is a supported bind-refusal source, not fabricated scan records.
	 */
	private static final class CountedSource {
		final NativeLmdbQuerySource source;
		final long buildPredicate, probePredicate;
		int probeHandles, closedProbeHandles, buildRefusals, scanOpens, scanCloses, buildOpens, probeOpens;
		long buildReturned, probeReturned, buildScanned, probeScanned;

		CountedSource(NativeLmdbQuerySource actual, long buildPredicate, long probePredicate) throws IOException {
			this.buildPredicate = buildPredicate;
			this.probePredicate = probePredicate;
			source = mock(NativeLmdbQuerySource.class, delegatesTo(actual));
			doAnswer(open -> {
				NativeProbe realProbe = actual.newProbe();
				probeHandles++;
				NativeProbe probe = mock(NativeProbe.class, delegatesTo(realProbe));
				// NativeProbe owns its last issued cursor. The kernel scanner reuses the probe and does not
				// individually close each returned iterator, so this wrapper must preserve that ownership.
				RecordIterator[] issued = new RecordIterator[1];
				doAnswer(close -> {
					try {
						RecordIterator current = issued[0];
						issued[0] = null;
						if (current != null) {
							current.close();
						}
					} finally {
						realProbe.close();
						closedProbeHandles++;
					}
					return null;
				}).when(probe).close();
				doAnswer(request -> {
					long predicate = request.getArgument(0);
					if (predicate == buildPredicate) {
						buildRefusals++;
						return null;
					}
					return realProbe.adjacency(predicate, request.getArgument(1));
				}).when(probe).adjacency(anyLong(), anyBoolean());
				doAnswer(request -> {
					RecordIterator previous = issued[0];
					issued[0] = null;
					if (previous != null) {
						previous.close();
					}
					return issued[0] = openScan(actual, request.getArgument(0), request.getArgument(1),
							request.getArgument(2), request.getArgument(3), request.getArgument(4));
				}).when(probe).open(anyLong(), anyLong(), anyLong(), anyLong(), any());
				return probe;
			}).when(source).newProbe();
		}

		private RecordIterator openScan(NativeLmdbQuerySource actual, long subject, long predicate, long object,
				long context, NativeLmdbQuerySource.AdjacencyAccessObserver observer) throws IOException {
			assertThat(predicate).isIn(buildPredicate, probePredicate);
			assertThat(object).as("the full object run stays free on every child scan")
					.isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			boolean build = subject == NativeLmdbQuerySource.UNKNOWN_ID;
			if (build) {
				assertThat(subject).isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				buildOpens++;
			} else {
				assertThat(subject).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				probeOpens++;
			}
			RecordIterator real = actual.lmdbStatements(subject, predicate, object, context, observer);
			scanOpens++;
			return new RecordIterator() {
				boolean closed;

				@Override
				public long[] next() {
					long[] result = real.next();
					if (result != null) {
						if (build) {
							buildReturned++;
						} else {
							probeReturned++;
						}
					}
					return result;
				}

				@Override
				public int fill(long[] target, int maxRows) {
					int count = real.fill(target, maxRows);
					if (build) {
						buildReturned += count;
					} else {
						probeReturned += count;
					}
					return count;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						try {
							assertThat(real.getIndexName()).contains(build ? "posc" : "spoc");
							long scanned = real.getSourceRowsScannedActual();
							assertThat(scanned).isPositive();
							if (build) {
								buildScanned += scanned;
							} else {
								probeScanned += scanned;
							}
						} finally {
							real.close();
							scanCloses++;
						}
					}
				}
			};
		}
	}
